        )))
        .unwrap();
        assert_eq!(inverses["files"].as_array().unwrap().len(), sources.len());
        for (index, (current, original, fixed_hash)) in sources.into_iter().enumerate() {
            assert_eq!(
                format!(
                    "{:x}",
                    crate::digest_hex::LowerHex(Sha256::digest(original.as_bytes()))
